const CACHE='ai-workbench-shell-v1';
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k!==CACHE)await caches.delete(k);await self.clients.claim()})()));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==self.location.origin||u.pathname.startsWith('/api')||e.request.method!=='GET')return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>new Response('<html lang="zh-CN"><meta name="viewport" content="width=device-width"><body style="font:16px system-ui;padding:40px;background:#f6f7f9"><h2>暂时连接不到电脑</h2><p>请确认工作电脑已开机、创作台正在运行，手机已连接 Tailscale。</p><p>恢复连接后重新打开。离线时不提交修改，避免丢失内容。</p><button onclick="location.reload()">重新连接</button></body></html>',{headers:{'Content-Type':'text/html;charset=utf-8'}})));return;}if(u.pathname.startsWith('/assets/')||u.pathname.startsWith('/icon'))e.respondWith(caches.open(CACHE).then(async c=>{const r=await c.match(e.request);if(r)return r;const f=await fetch(e.request);if(f.ok)c.put(e.request,f.clone());return f;}));});
